const TTPLUS = {};

TTPLUS.timers = {};
TTPLUS.observers = {};

/**
 * Interval object
 *
 * Sets the amount of update attempts that should be done
 */
TTPLUS.interval = {
  counter: 50,
  delay: 250,
};

/**
 * Different item modes (mode="X")
 */
TTPLUS.MODE = {
  FEED: "0",
  GRID: "1",
  BROWSER: "2",
  SWIPER_SLIDE: "3" /** Is this an obsolete mode? */,
  BASIC_PLAYER: "4",
};

/**
 * Sets the amount of item checks to do
 *
 * @param {integer} count
 */
TTPLUS.setInterval = (count) => {
  if (TTPLUS.interval.counter < count) {
    TTPLUS.interval.counter = count;
  }
};

/**
 * Different environments
 *
 * Default: `APP` is the main environment (most regions)
 * `__NEXT` has a different HTML structure, region-based and maybe obsolete now?
 */
TTPLUS.ENV = {
  APP: Symbol(true),
  __NEXT: Symbol(true),
};

TTPLUS.DEFAULT_ENV = TTPLUS.ENV.APP;

/**
 * `fetch` headers for requests
 *
 */
TTPLUS.headers = {
  method: "GET",
  mode: "cors",
  cache: "no-cache",
  credentials: "include",
  redirect: "follow",
};

export default TTPLUS;
