export const CHATGPT_URL = "chat.openai.com";

function runListener() {
  if (CHATGPT_URL === window.location.hostname) {
    if (document.getElementsByTagName("textarea")[0]) {
      document.getElementsByTagName("textarea")[0].focus();
      if ("?from=dn" !== window.location.search) return;
      chrome.runtime.sendMessage(chrome.runtime.id, { type: "OBSERVER_CHECK" }).then(() => {
        chrome.runtime.sendMessage(chrome.runtime.id, { type: "GET_PROMPT" }).then((data) => {
          console.log("data:", data);
          if (!data) return;
          setTimeout(() => {
            const textarea = document.getElementsByTagName("textarea")[0]
            textarea.value = data
            textarea.focus()
            textarea.dispatchEvent(new Event('input', {bubbles:true}))
            textarea.nextElementSibling.click()
          }, 200);
        });
      });
    }
  }
  // 复制
  async function copyText(text) {
    if (document.queryCommandSupported("copy")) {
      window.getSelection().removeAllRanges();
      const inputDom = document.createElement("input");
      // 要复制的内容dom节点
      const p = document.body;
      inputDom.value = text;
      p.appendChild(inputDom);
      const range = document.createRange();
      range.selectNode(inputDom);
      window.getSelection().addRange(range);
      inputDom.select();
      inputDom.setSelectionRange(0, inputDom.value.length);
      // 返回true 表示成功
      document.execCommand("copy");
      // 移除所有的range
      window.getSelection().removeAllRanges();
      p.removeChild(inputDom);
      return true;
    } else {
      await navigator.clipboard.writeText(text);
      await navigator.clipboard.readText();
      return true;
    }
  }

  function chatgpt_copy_run() {
    if (CHATGPT_URL !== window.location.hostname) return
    // if (location.href !== "chat.openai.com") return;
    const body = document.body;
    const observer = new MutationObserver(handleListChange);
    observer.observe(body, {
      subtree: true,
      attributes: true,
      characterData: true,
      childList: true,
    });
    handleListChange();
    // const nav = document.querySelector("nav");
    // new MutationObserver(handleListChange).observe(nav, {
    //   characterData: true,
    //   childList: true,
    // });
  }
  const copyClassName = "nc-copy-btn";
  const copySvg = `<svg style="filter: brightness(0.95)" width="24" height="24" viewBox="0 0 24 24" fill="none" class="nc-copy-svg ml-2" xmlns="http://www.w3.org/2000/svg">
    <path d="M7 6.6V5C7 4.44772 7.44772 4 8 4H18C18.5523 4 19 4.44772 19 5V16C19 16.5523 18.5523 17 18 17H16.2308" stroke="#828282" stroke-width="1.5" />
    <rect x="4.75" y="6.75" width="11.5" height="13.5" rx="1.25" stroke="#828282" stroke-width="1.5" />
  </svg>`;

  function handleListChange() {
    let list;
    try {
      list = document.querySelector("main").firstElementChild.firstElementChild.firstElementChild.firstElementChild.children;
      if (list.length < 2) return;
    } catch (error) {}
    if (!list) return;

    for (let i = 0; i < list.length; i++) {
      const responseNode = list[i];
      if (!responseNode.classList.contains("bg-gray-50")) continue;
      if (responseNode && responseNode.querySelector(".nc-copy-btn")) continue;
      if (!responseNode.firstElementChild) continue;
      const btn = document.createElement("button");
      btn.classList.add(...[copyClassName, "flex", "absolute"]);
      btn.innerHTML = `<span>Copy to Clipboard</span> ${copySvg}`;
      btn.style.right = "-168px";
      btn.addEventListener("click", async function () {
        await copyText(responseNode.firstElementChild.querySelector(".relative.flex-col.gap-1").textContent);
        btn.innerHTML = `<span>Copied</span> ${copySvg}`;
        setTimeout(() => {
          btn.innerHTML = `<span>Copy to Clipboard</span> ${copySvg}`;
        }, 2000);
      });
      responseNode.firstElementChild.appendChild(btn);
      responseNode.firstElementChild.classList.add("relative");
    }
  }

  // 入口
  chatgpt_copy_run();
}

export default runListener;
